const MP_16_9={0.2:"608×352",0.3:"736×416",0.4:"864×480",0.5:"960×544",0.6:"1056×608",0.7:"1152×640",0.8:"1216×672",0.9:"1280×736",0.98:"1344×768",1:"1376×768",1.2:"1504×832",1.5:"1664×928",1.8:"1824×1024",2:"1920×1088"};

function widget(node,name){return node.widgets?.find(w=>w.name===name);}
function promptInput(node){return node.inputs?.find(input=>input.name==="提示词"||input.widget?.name==="提示词");}
function promptIsLinked(node){const input=promptInput(node);return input?.link!=null;}
function choices(w){return w?.options?.values||w?.options?.items||[];}
function activeGenerationMode(node){return["文生视频","图生视频","首尾帧"].find(x=>!!widget(node,x)?.value)||"";}
function ratioChoicesForMode(node){const vals=choices(widget(node,"画面比例"));const mode=activeGenerationMode(node);return mode==="图生视频"||mode==="首尾帧"?vals:vals.filter(v=>v!=="原图比例");}
function setWidget(node,name,value){const w=widget(node,name);if(!w)return;if(typeof w.value==="number")value=Number(value);if(typeof w.value==="boolean")value=Boolean(value);w.value=value;w.callback?.(value);node.__nfh3UpdateSigmaProfile?.();node.__nfh3UpdateSecondPass?.();node.setDirtyCanvas(true,true);}
function isV3(node){return ["NanFengH3MultiReferenceGeneratorV3","NanFengH3MultiReferenceGeneratorV4","NanFengH3MultiReferenceGeneratorV5","NanFengH3MultiReferenceGeneratorV6"].includes(node.comfyClass)||["NanFengH3MultiReferenceGeneratorV3","NanFengH3MultiReferenceGeneratorV4","NanFengH3MultiReferenceGeneratorV5","NanFengH3MultiReferenceGeneratorV6"].includes(node.type);}
function isV4(node){return ["NanFengH3MultiReferenceGeneratorV4","NanFengH3MultiReferenceGeneratorV5","NanFengH3MultiReferenceGeneratorV6"].includes(node.comfyClass)||["NanFengH3MultiReferenceGeneratorV4","NanFengH3MultiReferenceGeneratorV5","NanFengH3MultiReferenceGeneratorV6"].includes(node.type);}
function isV5(node){return ["NanFengH3MultiReferenceGeneratorV5","NanFengH3MultiReferenceGeneratorV6"].includes(node.comfyClass)||["NanFengH3MultiReferenceGeneratorV5","NanFengH3MultiReferenceGeneratorV6"].includes(node.type);}

function hideWidget(w){if(!w)return;w.hidden=true;w.computeSize=()=>[0,-4];if(w.element)w.element.style.display="none";}
function valuesFor(node,kind){const out=[];for(let i=1;i<=LIMITS[kind];i++){const v=widget(node,`${kind}${i}`)?.value;if(v&&v!=="未选择")out.push(v);}return out;}
function writeValues(node,kind,values){for(let i=1;i<=LIMITS[kind];i++)setWidget(node,`${kind}${i}`,values[i-1]||"未选择");}
function inferKind(f){if(f.type.startsWith("image/"))return"图片";if(f.type.startsWith("video/"))return"视频";if(f.type.startsWith("audio/"))return"音频";const e=f.name.split(".").pop().toLowerCase();if(["png","jpg","jpeg","webp","bmp"].includes(e))return"图片";if(["mp4","mov","webm","mkv","avi"].includes(e))return"视频";if(["mp3","wav","flac"].includes(e))return"音频";}
function mediaUrl(f){return api.apiURL(`/view?filename=${encodeURIComponent(f)}&type=input`);}
async function upload(file){const b=new FormData();b.append("image",file);b.append("type","input");b.append("overwrite","true");const r=await api.fetchApi("/upload/image",{method:"POST",body:b});if(!r.ok)throw new Error(`上传失败 HTTP ${r.status}`);const d=await r.json();return d.subfolder?`${d.subfolder}/${d.name}`:d.name;}
function resolutionLabel(node){const ratio=widget(node,"画面比例")?.value,mp=Number(widget(node,"百万像素")?.value);if(ratio==="原图比例")return`原图比例 · ${mp} MP · 首帧只决定宽高比 · 最长边≤1920 · 最近32倍数`;const known=ratio==="16:9 (Widescreen)"?MP_16_9[mp]:null;if(known)return `${mp} MP · ${known} · multiple=32`;const p=String(ratio||"").match(/(\d+):(\d+)/);if(!p)return`${mp} MP`;const wr=+p[1],hr=+p[2],s=Math.sqrt(mp*1024*1024/(wr*hr));return`${mp} MP · ${Math.round(wr*s/32)*32}×${Math.round(hr*s/32)*32} · multiple=32`;}

