function cardAtPoint(x,y){for(const card of grid?.children||[]){const r=card.getBoundingClientRect();if(x>=r.left&&x<=r.right&&y>=r.top&&y<=r.bottom)return card;}return null;}
function swapCards(from,to){const next=valuesFor(node,active);if(!Number.isInteger(from)||!Number.isInteger(to)||from===to||from<0||from>=next.length)return false;if(to<next.length)[next[from],next[to]]=[next[to],next[from]];else{const[m]=next.splice(from,1);next.push(m);}writeValues(node,active,next);return true;}
function clearDragState(){dragIndex=null;if(dragCard)dragCard.classList.remove("dragging");dragCard=null;for(const q of root.querySelectorAll(".nfh3-card"))q.classList.remove("drag-target");}
function beginCardDrag(event,index,card){if(event.button!==0||event.target.closest?.(".nfh3-x,.nfh3-replace,audio,video,.nfh3-media-player"))return;event.preventDefault();event.stopPropagation();dragIndex=index;dragCard=card;card.classList.add("dragging");try{card.setPointerCapture?.(event.pointerId);}catch{} }
function moveCardDrag(event){if(dragIndex==null)return;event.preventDefault();event.stopPropagation();for(const q of root.querySelectorAll(".nfh3-card"))q.classList.remove("drag-target");cardAtPoint(event.clientX,event.clientY)?.classList.add("drag-target");}
function endCardDrag(event){if(dragIndex==null)return;event.preventDefault();event.stopPropagation();const target=cardAtPoint(event.clientX,event.clientY),to=target?Number(target.dataset.index):dragIndex,from=dragIndex;swapCards(from,to);clearDragState();render();}
node.__nfh3SwapCards=(kind,from,to)=>{active=kind;const changed=swapCards(from,to);render();return changed;};
root.addEventListener("pointermove",moveCardDrag,true);root.addEventListener("pointerup",endCardDrag,true);root.addEventListener("pointercancel",clearDragState,true);
