const promptBox=document.createElement("div");promptBox.className="nfh3-prompt";promptBox.innerHTML='<label><span>提示词</span><small class="nfh3-prompt-hint">输入 @ 选择已添加素材</small></label>';const promptHint=promptBox.querySelector(".nfh3-prompt-hint");const prompt=document.createElement("textarea");prompt.dataset.widgetName="提示词";prompt.value=widget(node,"提示词")?.value||"";const menu=document.createElement("div");menu.className="nfh3-mentions";promptBox.append(prompt,menu);
node.properties||={};const blankStoryboard=()=>({prompt:"",图片:[],视频:[],音频:[]});let shots=Array.isArray(node.properties.nanfeng_storyboards)&&node.properties.nanfeng_storyboards.length?node.properties.nanfeng_storyboards:[{prompt:prompt.value,图片:valuesFor(node,"图片"),视频:valuesFor(node,"视频"),音频:valuesFor(node,"音频")}];let activeShot=Math.max(0,Math.min(Number(node.properties.nanfeng_active_storyboard)||0,shots.length-1));const cloneStoryboard=shot=>typeof structuredClone==="function"?structuredClone(shot):JSON.parse(JSON.stringify(shot));const hydrateStoryboards=()=>{const saved=node.properties?.nanfeng_storyboards;if(Array.isArray(saved)&&saved.length){shots=cloneStoryboard(saved);activeShot=Math.max(0,Math.min(Number(node.properties.nanfeng_active_storyboard)||0,shots.length-1));return true;}return false;};const persistStoryboards=()=>{node.properties.nanfeng_storyboards=shots;node.properties.nanfeng_active_storyboard=activeShot;node.setDirtyCanvas?.(true,true);};const captureStoryboard=()=>{shots[activeShot]={prompt:prompt.value,图片:valuesFor(node,"图片"),视频:valuesFor(node,"视频"),音频:valuesFor(node,"音频")};persistStoryboards();};const applyStoryboard=(index,skipCapture=false)=>{if(!skipCapture)captureStoryboard();activeShot=Math.max(0,Math.min(index,shots.length-1));const shot=shots[activeShot]||blankStoryboard();setWidget(node,"提示词",shot.prompt||"");prompt.value=shot.prompt||"";for(const kind of Object.keys(LIMITS))writeValues(node,kind,Array.isArray(shot[kind])?shot[kind]:[]);persistStoryboards();render();};const storyboardBar=document.createElement("div");storyboardBar.className="nfh3-storyboard-bar";const storyboardTabs=document.createElement("div");storyboardTabs.className="nfh3-storyboard-tabs";const storyboardActions=document.createElement("div");storyboardActions.className="nfh3-storyboard-actions";const newShot=document.createElement("button");newShot.type="button";newShot.className="nfh3-storyboard-action";newShot.textContent="＋ 新建分镜";newShot.onclick=()=>{captureStoryboard();shots.push(blankStoryboard());applyStoryboard(shots.length-1,true);};const copyShot=document.createElement("button");copyShot.type="button";copyShot.className="nfh3-storyboard-action";copyShot.textContent="复制分镜";copyShot.onclick=()=>{captureStoryboard();shots.push(cloneStoryboard(shots[activeShot]));applyStoryboard(shots.length-1,true);};const deleteShot=document.createElement("button");deleteShot.type="button";deleteShot.className="nfh3-storyboard-action danger";deleteShot.textContent="删除分镜";deleteShot.onclick=()=>{if(shots.length<=1)return;shots.splice(activeShot,1);applyStoryboard(Math.min(activeShot,shots.length-1),true);};storyboardActions.append(newShot,copyShot,deleteShot);storyboardBar.append(storyboardTabs,storyboardActions);promptBox.append(storyboardBar);root.append(promptBox);
