function mentionItems(){const out=[];for(const k of Object.keys(LIMITS)){valuesFor(node,k).forEach((v,i)=>out.push({alias:`@${k}${i+1}`,kind:k,file:v}));}return out;}
function closeMentions(){menu.style.display="none";menu.replaceChildren();mentionButtons=[];mentionIndex=0;}
function nativeMention(it){const n=it.alias.match(/\d+$/)?.[0]||"1";if(it.kind==="图片")return`<Picture ${n}>`;if(it.kind==="视频")return`<Video ${n}>`;return`<Audio ${n}>`;}
function insertMention(it){const start=prompt.selectionStart,end=prompt.selectionEnd,before=prompt.value.slice(0,start),at=before.lastIndexOf("@");let from=at>=0?at:start;const mode=["文生视频","图生视频","首尾帧"].find(x=>!!widget(node,x)?.value)||"";let value=nativeMention(it);
// 多参图片统一一一绑定：@选择图片N，直接写入完整的 Subject N ↔ Picture N 定义。
if(!mode&&it.kind==="图片"){const n=it.alias.match(/\d+$/)?.[0]||"1";value=`<Subject ${n}> is the visual content referenced from <Picture ${n}>`;}
prompt.setRangeText(value,from,end,"end");commitPrompt();closeMentions();}
function selectMention(index){if(!mentionButtons.length)return;mentionIndex=(index+mentionButtons.length)%mentionButtons.length;mentionButtons.forEach((b,i)=>b.classList.toggle("active",i===mentionIndex));mentionButtons[mentionIndex].scrollIntoView({block:"nearest"});}
function openMentions(){const mode=["文生视频","图生视频","首尾帧"].find(x=>!!widget(node,x)?.value)||"";if(mode){closeMentions();return;}const items=mentionItems();menu.replaceChildren();mentionButtons=[];if(!items.length){const b=document.createElement("button");b.className="nfh3-mention";b.textContent="请先在下方添加图片、视频或音频";menu.append(b);}for(const it of items){const b=document.createElement("button");b.className="nfh3-mention";b.__mentionItem=it;b.dataset.native=nativeMention(it);if(it.kind==="图片"){const im=document.createElement("img");im.src=mediaUrl(it.file);b.append(im);}else{const ic=document.createElement("span");ic.className="nfh3-mention-icon";ic.textContent=it.kind==="视频"?"▶":"♫";b.append(ic);}const t=document.createElement("span");if(it.kind==="图片"){const n=it.alias.match(/\d+$/)?.[0]||"1";t.textContent=`<Subject ${n}> is the visual content referenced from <Picture ${n}> · ${it.file.split("/").pop()}`;}else t.textContent=`${b.dataset.native} · ${it.file.split("/").pop()}`;b.append(t);b.onmouseenter=()=>selectMention(mentionButtons.indexOf(b));b.onmousedown=e=>{e.preventDefault();insertMention(it);};menu.append(b);mentionButtons.push(b);}menu.style.display="block";selectMention(0);}
prompt.oninput=()=>{setWidget(node,"提示词",prompt.value);captureStoryboard();const mode=["文生视频","图生视频","首尾帧"].find(x=>!!widget(node,x)?.value)||"",before=prompt.value.slice(0,prompt.selectionStart);if(!mode&&/@[^\s@]*$/.test(before))openMentions();else closeMentions();};prompt.onkeydown=e=>{if(menu.style.display!=="none"&&mentionButtons.length){if(e.key==="ArrowDown"){e.preventDefault();selectMention(mentionIndex+1);return;}if(e.key==="ArrowUp"){e.preventDefault();selectMention(mentionIndex-1);return;}if(e.key==="Enter"){e.preventDefault();insertMention(mentionButtons[mentionIndex].__mentionItem);return;}}if(e.key==="Escape")closeMentions();};prompt.onblur=()=>setTimeout(closeMentions,120);
